package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.TypeBindings;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_addPropertyCreator_TriageGen2Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private AnnotatedWithParams creator;

    // Constant used in the method for verifyNonDup
    private static final int C_PROPS = 1; // Assuming C_PROPS is a constant in the class, adjust if needed

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        creator = mock(AnnotatedWithParams.class);
        // We use a spy to bypass/stub verifyNonDup since it is a protected method 
        // and we want to focus on the logic inside addPropertyCreator
        creatorCollector = spy(new CreatorCollector(beanDescription, true));
    }

    @Test
    public void testAddPropertyCreator_SingleProperty() {
        CreatorProperty prop = mock(CreatorProperty.class);
        when(prop.getName()).thenReturn("prop1");
        CreatorProperty[] properties = new CreatorProperty[]{prop};

        creatorCollector.addPropertyCreator(creator, true, properties);

        verify(creatorCollector).addPropertyCreator(creator, true, properties);
        // Success if no exception thrown
    }

    @Test
    public void testAddPropertyCreator_MultipleProperties_Success() {
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("prop1");

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("prop2");

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(creator, false, properties);
        // Success if no exception thrown
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddPropertyCreator_DuplicateNames_ThrowsException() {
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("duplicate");

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("duplicate");

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_InjectableWithEmptyName_SkipsDuplicateCheck() {
        // Case: name is empty, but it is an injectable (has ID), so it should be skipped and not trigger duplicate error
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("");
        when(prop1.getInjectableValueId()).thenReturn("someId");

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn("otherId");

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        // This should not throw IllegalArgumentException because of the 'continue' block
        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddPropertyCreator_DuplicateEmptyNames_NotInjectables_ThrowsException() {
        // Case: name is empty and NOT an injectable, should trigger duplicate check
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("");
        when(prop1.getInjectableValueId()).thenReturn(null);

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn(null);

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_EmptyPropertiesArray() {
        CreatorProperty[] properties = new CreatorProperty[0];
        creatorCollector.addPropertyCreator(creator, true, properties);
        // Success if no exception thrown
    }

    @Test
    public void testAddPropertyCreator_SingleProperty_NoDuplicateCheckLoop() {
        // properties.length is 1, so the loop block is skipped
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("onlyOne");
        CreatorProperty[] properties = new CreatorProperty[]{prop1};

        creatorCollector.addPropertyCreator(creator, true, properties);
        // Success if no exception thrown
    }
}

/**
 * Mocking internal classes for compilation purposes if they are not available in the environment.
 * In a real project, these are provided by Jackson.
 */
interface CreatorProperty {
    String getName();
    Object getInjectableValueId();
}

interface AnnotatedWithParams {}
